scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode || new global.EcsContext(engine.current).isClientOnly()) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsGlideRecord(ast).singleRecordReads();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-GR-005',
        title: 'Single-record read without setLimit(1)',
        recommendation: 'Add setLimit(1) before query() when only one record is read, or use get() for a lookup by a unique field.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
